#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "atax.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Use local restrict-qualified pointers to help the compiler with alias
 *    analysis and enable better vectorization.
 *  - Hoist the invariant denominator (5*m) out of the inner loop so it is
 *    computed only once.
 *  - Use row pointers (Ai) to avoid repeated address arithmetic on A[i][j].
 */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;
  DATA_TYPE fn = (DATA_TYPE)n;

  /* Local restrict-qualified views for better optimization. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_ = x;

  /* Initialize vector x. */
  for (i = 0; i < n; i++)
    x_[i] = SCALAR_VAL(1.0) + ((DATA_TYPE)i / fn);

  /* Precompute denominator used in A initialization.
   * This preserves original semantics: (DATA_TYPE)((i+j)%n) / (5*m).
   */
  const int denom_int = 5 * m;
  const DATA_TYPE denom = (DATA_TYPE)denom_int;

  /* Initialize matrix A. */
  for (i = 0; i < m; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];
    for (j = 0; j < n; j++)
      Ai[j] = ((DATA_TYPE)((i + j) % n)) / denom;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original computation:
 *   y = A^T * (A * x)
 *
 * Optimizations:
 *  - Introduce restrict-qualified local pointers for A, x, y, tmp to
 *    remove potential aliasing and enable aggressive vectorization.
 *  - Keep tmp[i] in a scalar register (tmp_i) while computing the dot
 *    product A[i][:] * x[:] and only write it back to tmp[i] once.
 *    This matches the original arithmetic order, but avoids repeated
 *    memory traffic on tmp[i].
 *  - Use a row pointer (Ai) so both inner loops operate on contiguous
 *    memory, improving cache locality and allowing efficient SIMD.
 *  - Preserve the original loop bounds and summation order for each
 *    element to maintain numerical behavior.
 */
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Local restrict-qualified views of the input arrays.
   * This is safe because the PolyBench macros allocate A, x, y, tmp
   * in disjoint memory regions in main().
   */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;
  DATA_TYPE *restrict tmp_    = tmp;

#pragma scop
  /* Initialize y to zero. */
  for (i = 0; i < _PB_N; i++)
    y_[i] = SCALAR_VAL(0.0);

  /* Main computation: tmp = A * x; y += A^T * tmp */
  for (i = 0; i < _PB_M; i++)
    {
      const DATA_TYPE *restrict Ai = A_[i];
      DATA_TYPE tmp_i = SCALAR_VAL(0.0);

      /* Compute tmp[i] = dot( A[i][:], x[:] )
       * The accumulation order over j is identical to the original code.
       */
      for (j = 0; j < _PB_N; j++)
        tmp_i += Ai[j] * x_[j];

      /* Store the result in tmp array (for consistency with original code). */
      tmp_[i] = tmp_i;

      /* Accumulate y[j] += A[i][j] * tmp[i] using the same i-then-j order
       * as the original implementation.
       */
      for (j = 0; j < _PB_N; j++)
        y_[j] += Ai[j] * tmp_i;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
