/* Include benchmark-specific header. */
#include "atax.h"


/* Array initialization.
 *
 * Optimizations:
 *  - Precompute constants that do not depend on i/j (denominator, 1.0).
 *  - Use a row pointer for A to improve locality and help the compiler.
 */
static
void init_array (int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n))
{
  int i, j;

  /* Cast once to DATA_TYPE instead of repeatedly inside the loop. */
  const DATA_TYPE fn    = (DATA_TYPE)n;
  const DATA_TYPE one   = SCALAR_VAL(1.0);
  const DATA_TYPE denom = SCALAR_VAL(5.0) * (DATA_TYPE)m;

  for (i = 0; i < n; i++)
    x[i] = one + ((DATA_TYPE)i / fn);

  for (i = 0; i < m; i++)
  {
    /* Row pointer: keeps inner loop indexing simple and friendly to the
     * optimizer and improves data locality for A.
     */
    DATA_TYPE* Ai = A[i];
    for (j = 0; j < n; j++)
      Ai[j] = ((DATA_TYPE)((i + j) % n)) / denom;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
		 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Original algorithm:
 *   tmp[i] = sum_j A[i][j] * x[j]
 *   y[j]   = sum_i A[i][j] * tmp[i]   (y is initialized to 0 beforehand)
 *
 * Optimizations (semantics preserved):
 *   - Introduce local `restrict` pointers (A_, x_, y_, tmp_) to tell the
 *     compiler that the arrays do not alias, enabling better vectorization.
 *   - Use a per-row scalar accumulator `ti` for tmp[i] instead of repeatedly
 *     reading and writing tmp[i] in the inner loops.
 *   - Compute tmp[i] in registers, store it once, and reuse the scalar for
 *     updating y[]; this removes a load of tmp[i] inside the j-loop.
 *   - Manually unroll both inner loops by a factor of 4 to improve
 *     instruction-level parallelism and make vectorization easier for GCC.
 *   - Preserve the exact order of floating-point operations (no reassociation),
 *     so numerical results are bitwise-identical to the original code.
 */
static
void kernel_atax[[gnu::flatten, gnu::noinline]](int m, int n,
		 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
		 DATA_TYPE POLYBENCH_1D(x,N,n),
		 DATA_TYPE POLYBENCH_1D(y,N,n),
		 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Local restricted views of the arrays.
   *
   * These assert to the compiler that:
   *   - A_, x_, y_, tmp_ point to non-overlapping regions.
   *   - Within the region where we use these pointers, we only access the
   *     underlying objects through them.
   *
   * This is true for this benchmark (arrays are separately allocated),
   * and it greatly helps the optimizer generate tight, vectorized code.
   */
  DATA_TYPE (* __restrict A_)[n] = A;
  DATA_TYPE * __restrict x_      = x;
  DATA_TYPE * __restrict y_      = y;
  DATA_TYPE * __restrict tmp_    = tmp;

  const int pb_m = _PB_M;
  const int pb_n = _PB_N;
  const DATA_TYPE zero = SCALAR_VAL(0.0);

#pragma scop
  /* Initialize y to zero. */
  for (i = 0; i < pb_n; i++)
    y_[i] = zero;

  /* Main computation: y = A^T * (A * x). */
  for (i = 0; i < pb_m; i++)
    {
      const DATA_TYPE * __restrict Ai = A_[i];

      /* Compute tmp[i] = dot(A[i][:], x[:]) in registers. */
      DATA_TYPE ti = zero;

      /* Manually unrolled dot-product loop (factor 4).
       * The operations are still applied in strictly increasing j order:
       *   (((0 + a0*x0) + a1*x1) + a2*x2) + a3*x3 + ...
       * so floating-point results remain identical to the original loop.
       */
      int j_unrolled = 0;
      for (j_unrolled = 0; j_unrolled <= pb_n - 4; j_unrolled += 4)
        {
          ti += Ai[j_unrolled    ] * x_[j_unrolled    ];
          ti += Ai[j_unrolled + 1] * x_[j_unrolled + 1];
          ti += Ai[j_unrolled + 2] * x_[j_unrolled + 2];
          ti += Ai[j_unrolled + 3] * x_[j_unrolled + 3];
        }

      /* Handle the remaining elements when pb_n is not a multiple of 4. */
      for (j = j_unrolled; j < pb_n; j++)
        ti += Ai[j] * x_[j];

      /* Store the final value of tmp[i] once. */
      tmp_[i] = ti;

      /* Use the scalar tmp[i] (now in `ti`) to update y.
       *
       * y[j] += A[i][j] * ti
       *
       * We again unroll by 4 while preserving the j iteration order.
       */
      DATA_TYPE scale = ti;

      int k = 0;
      for (k = 0; k <= pb_n - 4; k += 4)
        {
          y_[k    ] += Ai[k    ] * scale;
          y_[k + 1] += Ai[k + 1] * scale;
          y_[k + 2] += Ai[k + 2] * scale;
          y_[k + 3] += Ai[k + 3] * scale;
        }
      for (; k < pb_n; k++)
        y_[k] += Ai[k] * scale;
    }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
	       POLYBENCH_ARRAY(A),
	       POLYBENCH_ARRAY(x),
	       POLYBENCH_ARRAY(y),
	       POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
