  /* Local restrict-qualified views to improve optimization. */
  DATA_TYPE (*restrict A_)[n] = (DATA_TYPE (*restrict)[n])A;
  DATA_TYPE *restrict x_      = (DATA_TYPE *restrict)x;

  /* Denominator used in A initialization; computed once. This is
   * exactly equivalent to the original expression:
   *   ((DATA_TYPE)((i+j)%n)) / (5*m)
   * because (5*m) is computed in integer arithmetic and then
   * converted to DATA_TYPE.
   */
  const DATA_TYPE denom = (DATA_TYPE)(5 * m);

  /* Initialize x. */
  for (i = 0; i < n; i++)
    x_[i] = SCALAR_VAL(1.0) + ((DATA_TYPE)i) / fn;

  /* Initialize A. */
  for (i = 0; i < m; i++)
  {
    DATA_TYPE *restrict Ai = A_[i];
    for (j = 0; j < n; j++)
      Ai[j] = ((DATA_TYPE)((i + j) % n)) / denom;
  }
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int n,
                 DATA_TYPE POLYBENCH_1D(y,N,n))

{
  int i;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("y");
  for (i = 0; i < n; i++) {
    if (i % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
    fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, y[i]);
  }
  POLYBENCH_DUMP_END("y");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.
 *
 * Optimizations:
 *  - Introduce restrict-qualified local pointers for A, x, y, tmp
 *    to give the compiler precise aliasing information.
 *  - Keep row pointers (Ai) and scalar accumulators (tmp_val) in
 *    registers to reduce memory traffic.
 *  - Manually unroll inner loops by a factor of 4 while preserving
 *    the exact per-element accumulation order, which improves
 *    instruction-level parallelism and reduces loop overhead without
 *    changing floating-point semantics of the original code.
 *  - Preserve the overall loop nesting and the order of updates to
 *    each y[j], ensuring numerically identical results.
 */
static
void kernel_atax [[gnu::flatten, gnu::noinline]] (int m, int n,
                 DATA_TYPE POLYBENCH_2D(A,M,N,m,n),
                 DATA_TYPE POLYBENCH_1D(x,N,n),
                 DATA_TYPE POLYBENCH_1D(y,N,n),
                 DATA_TYPE POLYBENCH_1D(tmp,M,m))
{
  int i, j;

  /* Local restrict-qualified aliases to help vectorization
   * and avoid pessimistic alias assumptions.
   */
  DATA_TYPE (*restrict A_)[n] = (DATA_TYPE (*restrict)[n])A;
  DATA_TYPE *restrict x_      = (DATA_TYPE *restrict)x;
  DATA_TYPE *restrict y_      = (DATA_TYPE *restrict)y;
  DATA_TYPE *restrict tmp_    = (DATA_TYPE *restrict)tmp;

  const int pb_m = _PB_M;
  const int pb_n = _PB_N;

#pragma scop
  /* Initialize y to zero (live-out array). Using SCALAR_VAL
   * keeps the type consistent with DATA_TYPE. */
  for (j = 0; j < pb_n; j++)
    y_[j] = SCALAR_VAL(0.0);

  /* ATAX: y = A^T * (A * x) */
  for (i = 0; i < pb_m; i++)
  {
    const DATA_TYPE *restrict Ai = A_[i];
    DATA_TYPE tmp_val = SCALAR_VAL(0.0);

    /* First stage: tmp[i] = dot( A[i][:], x[:] ).
     *
     * Manual unrolling by 4 keeps the accumulation order over j
     * identical to the original loop (0,1,2,3,4,...) while reducing
     * loop control overhead and exposing more ILP.
     */
    int j_unroll = 0;
    for (; j_unroll + 3 < pb_n; j_unroll += 4)
    {
      tmp_val += Ai[j_unroll]     * x_[j_unroll];
      tmp_val += Ai[j_unroll + 1] * x_[j_unroll + 1];
      tmp_val += Ai[j_unroll + 2] * x_[j_unroll + 2];
      tmp_val += Ai[j_unroll + 3] * x_[j_unroll + 3];
    }
    for (; j_unroll < pb_n; j_unroll++)
      tmp_val += Ai[j_unroll] * x_[j_unroll];

    /* Store tmp[i] exactly as in the original code so that the
     * tmp array contents are preserved. */
    tmp_[i] = tmp_val;

    /* Second stage: y[:] += tmp[i] * A[i][:].
     *
     * We reuse Ai and tmp_val to minimize memory traffic.
     * Unrolling by 4 again preserves the exact order of updates
     * to each y[j]; for a fixed j, contributions from i are applied
     * in the same order as in the original implementation.
     */
    j_unroll = 0;
    for (; j_unroll + 3 < pb_n; j_unroll += 4)
    {
      y_[j_unroll]     += Ai[j_unroll]     * tmp_val;
      y_[j_unroll + 1] += Ai[j_unroll + 1] * tmp_val;
      y_[j_unroll + 2] += Ai[j_unroll + 2] * tmp_val;
      y_[j_unroll + 3] += Ai[j_unroll + 3] * tmp_val;
    }
    for (; j_unroll < pb_n; j_unroll++)
      y_[j_unroll] += Ai[j_unroll] * tmp_val;
  }
#pragma endscop

}


