     This tells the compiler that A, x, y, and tmp do not overlap in
     memory, enabling more aggressive vectorization and reordering. */
  DATA_TYPE (*restrict A_)[n] = A;
  DATA_TYPE *restrict x_      = x;
  DATA_TYPE *restrict y_      = y;
  DATA_TYPE *restrict tmp_    = tmp;

#pragma scop
  /* Initialize y to zero. Using SCALAR_VAL ensures the right DATA_TYPE. */
  for (i = 0; i < _PB_N; i++)
    y_[i] = SCALAR_VAL(0.0);

  /* Compute y = A^T * (A * x).
     For each row i:
       1) tmp[i] = dot( A[i,:], x )
       2) y[:]  += A[i,:] * tmp[i]
     We keep tmp[i] in a scalar register 't' while computing it and
     then reuse the same scalar in the second loop. A pointer to the
     current row Ai improves locality and reduces address arithmetic. */
  for (i = 0; i < _PB_M; i++)
  {
    DATA_TYPE t = SCALAR_VAL(0.0);
    DATA_TYPE *restrict Ai = A_[i];

    /* tmp[i] = A[i,:] * x */
    for (j = 0; j < _PB_N; j++)
      t += Ai[j] * x_[j];

    /* Preserve original behavior: write tmp[i] to the tmp array. */
    tmp_[i] = t;

    /* y[:] += A[i,:] * tmp[i] */
    for (j = 0; j < _PB_N; j++)
      y_[j] += Ai[j] * t;
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int m = M;
  int n = N;

  /* Variable declaration/allocation. */
  POLYBENCH_2D_ARRAY_DECL(A, DATA_TYPE, M, N, m, n);
  POLYBENCH_1D_ARRAY_DECL(x, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(y, DATA_TYPE, N, n);
  POLYBENCH_1D_ARRAY_DECL(tmp, DATA_TYPE, M, m);

  /* Initialize array(s). */
  init_array (m, n, POLYBENCH_ARRAY(A), POLYBENCH_ARRAY(x));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_atax (m, n,
               POLYBENCH_ARRAY(A),
               POLYBENCH_ARRAY(x),
               POLYBENCH_ARRAY(y),
               POLYBENCH_ARRAY(tmp));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(n, POLYBENCH_ARRAY(y)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(x);
  POLYBENCH_FREE_ARRAY(y);
  POLYBENCH_FREE_ARRAY(tmp);

  return 0;
}
